1	package com.example.starter.wb.calc;
2	
3	import com.example.starter.wb.domain.Aircraft;
4	import com.example.starter.wb.domain.EnvelopePoint;
5	
6	import java.math.BigDecimal;
7	import java.math.RoundingMode;
8	import java.util.ArrayList;
9	import java.util.List;
10	
11	/**
12	 * 载重与平衡纯计算：业载合计、ZFW/TOW、力矩与 %MAC 重心，
13	 * 并按“总业载 ≤ MZFW−OEW（恰等合法）、重心在包线内（恰边界合法）”判定。
14	 * 所有结果可由明细完整复算。
15	 */
16	public final class WeightBalanceCalculator {
17	
18	    private static final int CG_SCALE = 4;
19	    private static final int MOMENT_SCALE = 2;
20	    private static final BigDecimal HUNDRED = BigDecimal.valueOf(100);
21	
22	    private WeightBalanceCalculator() {
23	    }
24	
25	    public static WeightBalanceResult calculate(Aircraft ac, List<CalcLoadItem> items, BigDecimal fuelKg) {
26	        BigDecimal payload = BigDecimal.ZERO.setScale(MOMENT_SCALE);
27	        BigDecimal payloadMoment = BigDecimal.ZERO.setScale(MOMENT_SCALE);
28	        int pax = 0;
29	        for (CalcLoadItem item : items) {
30	            payload = payload.add(item.weightKg());
31	            payloadMoment = payloadMoment.add(item.moment());
32	            if (item.isPassenger()) {
33	                pax += item.pieces();
34	            }
35	        }
36	
37	        BigDecimal oew = BigDecimal.valueOf(ac.oewKg());
38	        BigDecimal fuel = fuelKg.setScale(MOMENT_SCALE, RoundingMode.HALF_UP);
39	        BigDecimal zfw = oew.add(payload);
40	        BigDecimal tow = zfw.add(fuel);
41	
42	        BigDecimal zfwMoment = oew.multiply(ac.oewArm()).add(payloadMoment);
43	        BigDecimal towMoment = zfwMoment.add(fuel.multiply(ac.fuelArm()));
44	
45	        BigDecimal cgZfw = toMacPct(ac, zfwMoment.divide(zfw, 6, RoundingMode.HALF_UP));
46	        BigDecimal cgTow = toMacPct(ac, towMoment.divide(tow, 6, RoundingMode.HALF_UP));
47	
48	        List<String> violations = new ArrayList<>();
49	        BigDecimal payloadLimit = BigDecimal.valueOf(ac.mzfwKg() - ac.oewKg());
