        jdbc.execute("DELETE FROM review_confirmation");
        jdbc.execute("DELETE FROM lmc_log");
        jdbc.execute("DELETE FROM late_event");
        jdbc.execute("DELETE FROM manifest_version");
        jdbc.execute("DELETE FROM idempotent_request");
    }
}

