        rest().perform(post("/api/flights/1/loadsheet/review").contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"%s","role":"FLIGHT_DISPATCHER","reviewer":"fd002"}"""
                                .formatted(UUID.randomUUID())))
